// Generated by cmd/gen: a smoke test of the 通知公告 API. It needs the table
// to be created by a migration. Extend it with the resource's own rules.

// noticeTestGuard admits every request as a super admin with full data
// scope; permission enforcement is covered by the app tests.
type noticeTestGuard struct{}

func (noticeTestGuard) Require(access.Level) gin.HandlerFunc {
	return func(c *gin.Context) {
		a := &actor.Actor{Snapshot: &actor.Snapshot{UserID: 1, IsSuper: true, DataScope: datascope.Resolved{All: true}}}
		c.Request = c.Request.WithContext(actor.With(c.Request.Context(), a))
	}
}

type noticeEnvelope struct {
	Code int             `json:"code"`
	Data json.RawMessage `json:"data"`
}

func newNoticeTestServer(t *testing.T) http.Handler {
	t.Helper()
	gin.SetMode(gin.TestMode)
	cfg := migrated.Database(t)
	sqlDB, err := database.OpenSQL(context.Background(), cfg, "notice-test")
	require.NoError(t, err)
	t.Cleanup(func() { _ = sqlDB.Close() })
	db, err := database.NewGorm(sqlDB, cfg, zap.NewNop())
	require.NoError(t, err)
	engine := gin.New()
	m := New(Deps{DB: db})
	m.noticeRoutes(module.NewRouter(engine.Group("/api/v1"), Name, noticeTestGuard{}, module.NewRegistry()))
	return engine
}

func callNotice(t *testing.T, h http.Handler, method, path string, body any) (int, noticeEnvelope) {
	t.Helper()
	var buf bytes.Buffer
	if body != nil {
		require.NoError(t, json.NewEncoder(&buf).Encode(body))
	}
	req := httptest.NewRequest(method, path, &buf)
	req.Header.Set("Content-Type", "application/json")
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	var env noticeEnvelope
	if strings.HasPrefix(rec.Header().Get("Content-Type"), "application/json") {
		require.NoError(t, json.Unmarshal(rec.Body.Bytes(), &env))
	}
	return rec.Code, env
}

func TestNoticeCRUD(t *testing.T) {
	h := newNoticeTestServer(t)
	const base = "/api/v1/notices"
	// Adjust the sample values to satisfy foreign keys and business rules.
	payload := map[string]any{
		"title":   "示例标题",
		"type":    1,
		"content": "示例内容",
	}

	status, env := callNotice(t, h, http.MethodPost, base, payload)
	require.Equal(t, http.StatusOK, status, string(env.Data))
	var created struct {
		ID      string `json:"id"`
		Version int    `json:"version"`
	}
	require.NoError(t, json.Unmarshal(env.Data, &created))
	require.NotEmpty(t, created.ID)

	status, env = callNotice(t, h, http.MethodGet, base+"?page=1&pageSize=10", nil)
	require.Equal(t, http.StatusOK, status)
	var page struct {
		Total int64 `json:"total"`
	}
	require.NoError(t, json.Unmarshal(env.Data, &page))
	assert.Equal(t, int64(1), page.Total)

	status, _ = callNotice(t, h, http.MethodGet, base+"/"+created.ID, nil)
	assert.Equal(t, http.StatusOK, status)

	payload["version"] = created.Version
	status, env = callNotice(t, h, http.MethodPut, base+"/"+created.ID, payload)
	require.Equal(t, http.StatusOK, status, string(env.Data))
	status, _ = callNotice(t, h, http.MethodPut, base+"/"+created.ID, payload)
	assert.Equal(t, http.StatusConflict, status, "a stale version is rejected")

	status, _ = callNotice(t, h, http.MethodDelete, base+"/"+created.ID, nil)
	require.Equal(t, http.StatusOK, status)
	status, _ = callNotice(t, h, http.MethodGet, base+"/"+created.ID, nil)
	assert.Equal(t, http.StatusNotFound, status)
}

func TestNoticeValidation(t *testing.T) {
	h := newNoticeTestServer(t)
	status, env := callNotice(t, h, http.MethodPost, "/api/v1/notices", map[string]any{})
	assert.Equal(t, http.StatusUnprocessableEntity, status)
	assert.Equal(t, 10002, env.Code)
}

func TestNoticeFilters(t *testing.T) {
	h := newNoticeTestServer(t)
	// Every search parameter is accepted and applied to the query.
	status, env := callNotice(t, h, http.MethodGet, "/api/v1/notices?page=1&pageSize=10&title=x&type=1", nil)
	assert.Equal(t, http.StatusOK, status, string(env.Data))
}
